{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"nvidiaTeslaT4","dataSources":[{"sourceType":"competition","sourceId":143716}],"dockerImageVersionId":31401,"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":true}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"import numpy as np # linear algebra\nimport pandas as pd # data processing, CSV file I/O (e.g. pd.read_csv)\n\n# Input data files are available in the read-only \"../input/\" directory\n# For example, running this (by clicking run or pressing Shift+Enter) will list all files under the input directory\n\nimport os\nfor dirname, _, filenames in os.walk('/kaggle/input'):\n    for filename in filenames:\n        print(os.path.join(dirname, filename))\n\n# You can write up to 20GB to the current directory (/kaggle/working/) that gets preserved as output when you create a version using \"Save & Run All\" \n# You can also write temporary files to /kaggle/temp/, but they won't be saved outside of the current session\n\n# Use the kagglehub client library to attach Kaggle resources like competitions, datasets, and models to your session\n# Learn more about kagglehub: https://github.com/Kaggle/kagglehub/blob/main/README.md\n\n# ____________________________________________________________________________________________________\n# 1. imports\nimport os\nimport gc\nimport random\n\nimport numpy as np\nimport pandas as pd\n\nimport torch\nfrom torch.utils.data import Dataset, DataLoader\nfrom torch.optim import AdamW\n\nimport wandb\nimport kagglehub\n\nfrom kaggle_secrets import UserSecretsClient\n\nfrom sklearn.model_selection import StratifiedKFold\n\nfrom transformers import (\n    AutoTokenizer,\n    AutoModelForSequenceClassification,\n    DataCollatorWithPadding,\n    get_linear_schedule_with_warmup,\n)\n\n# ____________________________________________________________________________________________________\n# 2. Setup\n#2.1 - downlaod competition\nkagglehub.competition_download('smart-mcq-solver-challenge')\n\n# 2.2 - initialize dataframe\n# df = pd.read_csv(\"/kaggle/input/competitions/smart-mcq-solver-challenge/train.csv\")\n\n# 2.3 - SEED (for repeatability)\nSEED = 42\nrandom.seed(SEED)\nnp.random.seed(SEED)\ntorch.manual_seed(SEED)\nif torch.cuda.is_available():\n    torch.cuda.manual_seed_all(SEED)\n\n# 2.4 - Weights and Biases setup\nuser_secrets = UserSecretsClient()\nwandb_api_key = user_secrets.get_secret(\"WANB_API_KEY\")\n\n\nwandb.login(\n    key=wandb_api_key\n)\n\n#2.5 - Constants\nBATCH_SIZE = 16\ndevice = torch.device(\n    \"cuda\" if torch.cuda.is_available() else \"cpu\"\n)\nFOLDS = 5\nMODEL_NAME = \"microsoft/deberta-v3-base\"\nSTAGE1_EPOCHS = 8\nSTAGE2_EPOCHS = 5\nMAX_LENGTH = 256\n\n# ____________________________________________________________________________________________________\n# ____________________________________________________________________________________________________\n# ____________________________________________________________________________________________________\n# 3. Functions and Auxilary functional elements\n\n#3.1 - MAP@3 function\n# takes two inputs, one is a list of all correct answers, the other a list of corresponding predictions\ndef map_at_3(y_true, y_pred):\n    score = 0.0\n\n    if len(y_true) != len(y_pred):\n        raise ValueError(\"Length mismatch\")\n\n    for i in range(len(y_true)):\n        pred = y_pred[i]\n        true = y_true[i]\n        if true in pred:\n            for j in range(len(pred)):\n                if pred[j] == true:\n                    score += 1/(j+1)\n                    break\n                \n    return score/len(y_true)\n\n# ____________________________________________________________________________________________________\n# 3.2 - expands dataset \n# takes in a row and creates 5 corresponding rows for each option with whether it is correct or not.\ndef expand_dataset(df):\n    samples = []\n\n    for _, row in df.iterrows():\n        \n        for option in [\"A\",\"B\",\"C\",\"D\",\"E\"]:\n            samples.append({\n                'prompt': row['prompt'],\n\n                'option': row[option],\n                \n                \"label\": 1 if option == row[\"answer\"] else 0,\n    \n                \"question_id\": row[\"id\"]\n            })\n\n    return pd.DataFrame(samples)\n\n# ____________________________________________________________________________________________________\n# 3.3 - MCQDataset Class for making table into an object\n# create MCQDATASET class\nclass MCQDataset(Dataset):\n    def __init__(self, dataframe, tokenizer):\n        self.prompts = dataframe['prompt'].tolist()\n        self.options = dataframe['option'].tolist()\n        self.labels = dataframe['label'].tolist()\n        self.tokenizer = tokenizer\n\n    def __len__(self):\n        return len(self.labels)\n\n    def __getitem__(self, idx):\n        encoding = self.tokenizer(\n            self.prompts[idx],\n            self.options[idx],\n            truncation=True,\n            max_length=256\n        )\n\n        return {\n            \"input_ids\":\n                encoding['input_ids'],\n\n            \"attention_mask\":\n                encoding['attention_mask'],\n\n            \"labels\": int(self.labels[idx])\n        }\n\n# ____________________________________________________________________________________________________\n# 3.4 - process data to prepare it for training\n# takes in a dataframe and returns dataloader for training\ndef process_data(dataframe, tokenizer, shuffle):\n    expanded_df = expand_dataset(dataframe)\n    data_object = MCQDataset(expanded_df, tokenizer)\n\n    # data collator\n    data_collator = DataCollatorWithPadding(\n        tokenizer=tokenizer,\n        return_tensors=\"pt\"\n    )\n\n    data_loader = DataLoader(\n        data_object,\n        batch_size=BATCH_SIZE,\n        shuffle=shuffle,\n        collate_fn=data_collator,\n        num_workers=2,\n        pin_memory=True,\n        persistent_workers=True\n    )\n\n    return data_loader\n\n# ____________________________________________________________________________________________________\n# 3.5 - the actual training loop\ndef train_model(\n    model,\n    tokenizer,\n    train_loader,\n    val_loader,\n    optimizer,\n    scheduler,\n    epochs,\n    save_dir\n):\n    lowest_val_loss = float(\"inf\")\n    best_accuracy = 0\n\n    for epoch in range(epochs):\n        \n        # Training - put model into training mode\n        model.train()\n\n        train_loss = 0\n\n        for batch in train_loader:\n            # basically move the data to gpu for computation\n            input_ids = batch[\"input_ids\"].to(device)\n            attention_mask = batch[\"attention_mask\"].to(device)\n            # to convert them to floats32 for single precision calculations\n            labels = batch[\"labels\"].long().to(device)\n\n            optimizer.zero_grad()\n\n            outputs = model(\n                input_ids = input_ids,\n                attention_mask = attention_mask,\n                labels=labels\n            )\n            \n            loss = outputs.loss\n            loss.backward()\n            optimizer.step()\n            scheduler.step()\n            train_loss += loss.item()\n\n        train_loss /= len(train_loader)\n\n        # Evaluation\n        model.eval()\n        \n        val_loss = 0\n\n        correct = 0\n    \n        total = 0\n\n        with torch.no_grad():\n            for batch in val_loader:\n                # basically move the data to gpu for computation\n                input_ids = batch[\"input_ids\"].to(device)\n                attention_mask = batch[\"attention_mask\"].to(device)\n                # to convert them to floats32 for single precision calculations\n                labels = batch[\"labels\"].long().to(device)\n    \n                outputs = model(\n                    input_ids = input_ids,\n                    attention_mask = attention_mask,\n                    labels=labels\n                )\n\n                val_loss += outputs.loss.item()\n                \n                predictions = torch.argmax(\n                    outputs.logits,\n                    dim=1\n                )\n                \n                correct += (predictions == labels).sum().item()\n\n                total += labels.size(0)\n\n        val_loss /= len(val_loader)\n\n        accuracy = correct/total\n\n        ##################################\n        # Save Best Model\n        ##################################\n        if val_loss < lowest_val_loss:\n            best_accuracy = accuracy\n            \n            lowest_val_loss = val_loss\n    \n            model.save_pretrained(save_dir)\n    \n            tokenizer.save_pretrained(save_dir)\n    \n            artifact = wandb.Artifact(\n    \n                save_dir,\n    \n                type=\"model\"\n    \n            )\n    \n            artifact.add_dir(save_dir)\n    \n            wandb.log_artifact(artifact)\n\n        \n         ##################################\n        # W&B Logging\n        ##################################\n    \n        wandb.log({\n    \n            \"epoch\": epoch + 1,\n    \n            \"train_loss\": train_loss,\n    \n            \"validation_loss\": val_loss,\n    \n            \"validation_accuracy\": accuracy,\n    \n            \"learning_rate\": scheduler.get_last_lr()[0],\n    \n            \"lowest validation loss\": lowest_val_loss\n    \n        })\n    \n        ##################################\n        # Console\n        ##################################\n    \n        print(\n    \n            f\"Epoch {epoch+1}/{epochs}\"\n    \n            f\" | Train Loss: {train_loss:.4f}\"\n    \n            f\" | Val Loss: {val_loss:.4f}\"\n    \n            f\" | Best Accuracy: {best_accuracy:.4f}\"\n    \n        )\n    \n    print(f\"\\nLowest Validation Loss: {lowest_val_loss:.4f}\")\n\n    return {\n        'loss': lowest_val_loss,\n        'accuracy': accuracy,\n        'checkpoint': save_dir\n    }\n\n# 3.6 - clean up between stages and folds\ndef clear_data(model, optimizer, scheduler):\n    try:\n        del model\n        del optimizer\n        del scheduler\n\n        torch.cuda.synchronize()\n        torch.cuda.empty_cache()\n        gc.collect()\n    \n    except Exception as e:\n        return(\"could not clean up model, optimizer and scheduler\", e)\n\n    return\n\ndef upload_models():\n    for fold in range(1, (FOLDS+1)):\n        kagglehub.model_upload(\n            handle=f\"siddharthavarma12/deberta-v3-base/fold{fold}-stage1\",\n            local_model_dir=f\"best_model_fold{fold}_stage1\"\n        )\n    \n        kagglehub.model_upload(\n            handle=f\"siddharthavarma12/deberta-v3-base/fold{fold}-stage2\",\n            local_model_dir=f\"best_model_fold{fold}_stage2\"\n        )\n\n# ____________________________________________________________________________________________________\n# ____________________________________________________________________________________________________\n# ____________________________________________________________________________________________________\ndef main():\n    df = pd.read_csv(\"/kaggle/input/competitions/smart-mcq-solver-challenge/train.csv\")\n\n    kf = StratifiedKFold(\n        n_splits=FOLDS,\n        shuffle=True,\n        random_state=SEED\n    )\n\n    for fold, (train_idx, val_idx) in enumerate(\n        kf.split(df, df['answer']),\n        start=1\n    ):\n        print(f\"\\n========== Fold {fold} ==========\\n\")\n\n        train_df = df.iloc[train_idx].reset_index(drop=True)\n        val_df = df.iloc[val_idx].reset_index(drop=True)\n        tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME)\n        model = AutoModelForSequenceClassification.from_pretrained(\n            MODEL_NAME,\n            num_labels=2,\n            dtype=torch.float32\n        )\n\n        model = model.to(device)\n\n        train_loader = process_data(\n            train_df,\n            tokenizer,\n            True\n        )\n\n        val_loader = process_data(\n            val_df,\n            tokenizer,\n            False\n        )\n\n        # Stage - 1 \n        # Setup\n        # optimizer\n        optimizer1 = AdamW(\n            model.parameters(),\n            lr=5e-6,\n            weight_decay=0.01\n        )\n\n        # scheduler\n        scheduler1 = get_linear_schedule_with_warmup(\n            optimizer1,\n            num_warmup_steps=int(0.1 * (len(train_loader) * STAGE1_EPOCHS)),\n            num_training_steps=(len(train_loader) * STAGE1_EPOCHS)\n        )\n\n        wandb.init(\n\n            project=\"24f1002705-DLGenAI-t12026\",\n        \n            name=f\"deberta-v3-base-fold{fold}_stage1\",\n        \n            config={\n        \n                \"model\": MODEL_NAME,\n                \"epochs\": STAGE1_EPOCHS,\n                \"batch_size\": 16,\n                \"learning_rate\": 5e-6,\n                \"max_length\": MAX_LENGTH,\n                \"optimizer\": \"AdamW\",\n                \"scheduler\": \"Linear Warmup\"\n        \n            }\n        \n        )\n\n        # trainer\n        train_model(\n            model,\n            tokenizer,\n            train_loader,\n            val_loader,\n            optimizer1,\n            scheduler1,\n            STAGE1_EPOCHS,\n            f\"best_model_fold{fold}_stage1\"\n        )\n\n        wandb.finish()\n\n        # interstage clean up\n        clear_data(model, optimizer1, scheduler1)\n\nif __name__ == \"__main__\":\n\n    main()\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-07-08T14:12:48.263229Z\",\"iopub.execute_input\":\"2026-07-08T14:12:48.264045Z\",\"iopub.status.idle\":\"2026-07-08T14:21:54.609946Z\",\"shell.execute_reply.started\":\"2026-07-08T14:12:48.264011Z\",\"shell.execute_reply\":\"2026-07-08T14:21:54.609194Z\"}}\nimport os\nfrom IPython.display import FileLink\n\n# Zip all contents of the working directory\n!zip -r all_files.zip /kaggle/working\n\n# Create and display the direct download link\nFileLink(r'all_files.zip')","metadata":{"_uuid":"e1038230-81d8-4b80-93f4-13847ff70458","_cell_guid":"92c8089b-0487-4a5d-80ee-a28a514244b8","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}